+.joystick{width:88px;height:88px;position:relative;display:grid;place-items:center;border:1px solid #fff9;border-radius:50%;background:radial-gradient(circle at 50% 42%,#fffaf0d9,#e7ecd5de 68%,#d1ddc2e8);box-shadow:0 4px 14px #263b2b30,inset 0 2px 6px #fff9;pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none}
+.joystick:before{content:'';position:absolute;width:60%;height:60%;border:1px dashed #82977a75;border-radius:50%}
+.joystick-thumb{position:absolute;width:32px;height:32px;border-radius:50%;background:linear-gradient(145deg,#91aa7f,#617d63);border:2px solid #f8f6e8;box-shadow:0 3px 8px #2c443b55;transition:transform .06s ease-out;will-change:transform}
+.walk-use{width:66px;height:66px;border:2px solid #f8f6e8;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;background:linear-gradient(145deg,#e3ae77,#c9865e);color:#fffdf1;box-shadow:0 4px 12px #40372842;pointer-events:auto;touch-action:manipulation;cursor:pointer}
+.walk-use span{font-size:21px;line-height:1}.walk-use small{font:7px var(--pixel);letter-spacing:.3px}
+.joystick:focus-visible,.walk-use:focus-visible{outline:3px solid #fff;outline-offset:3px}
